xml.Script:
        Colors[0] := 'FFFF00'; // Yellow
        Colors[1] := '0044EE'; // Blue
        Colors[2] := 'BB00BB'; // Violet
        Colors[3] := 'DD0000'; // Red
        Colors[4] := '0088FF'; // Light Blue
        Colors[5] := 'FF7700'; // Ogange
        Colors[6] := '00BB00'; // Green

        R := 0.6;
        H := R * 2.25;

        for i := 0 to 5 do begin
            x[i] := R * cos(Pi / 3 * (i + 0.5));
            y[i] := R * sin(Pi / 3 * (i + 0.5));
        end;

        for i := 0 to 2 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;

        D := H / 9;

        Z := -D * 3; // z-coordinate of Bottom

        dZ := H * 0.1; // vertical slide
